#include <assert.h>
#include <inttypes.h>
#include <stdio.h>

#ifndef TERM_IMPLEMENTATION
#define TERM_IMPLEMENTATION "/home/lim/portfolio/ppap/src/X/term.c"
#endif
#include TERM_IMPLEMENTATION

static void print_wire(HolTermStore *store, const char *label, HTerm term)
{
    int64_t *wire = NULL;
    size_t count = 0;
    assert(ht_export(store, ht_normalize(store, term, HT_NF), &wire, &count));
    printf("%s:", label);
    for (size_t i = 0; i < count; ++i) {
        printf(" %" PRId64, wire[i]);
    }
    putchar('\n');
    free(wire);
}

int main(void)
{
    HolTermStore *store = ht_create();
    assert(store);
    HTCheckpoint checkpoint = ht_checkpoint(store);
    for (size_t i = 0; i < 100000; ++i) {
        assert(ht_var(store, 0, 0, -1) != HT_NONE);
        assert(ht_restore(store, checkpoint));
    }
    printf("retirement: nodes=%zu node_capacity=%zu identity_count=%zu identity_capacity=%zu identity_bytes=%zu next_uid=%" PRIu64 "\n",
        store->count, store->capacity, store->identity_count, store->identity_capacity,
        store->identity_capacity * sizeof(Identity), store->next_uid);
    printf("history: ranges=%zu capacity=%zu bytes=%zu term_node_size=%zu\n",
        store->retired_count, store->retired_capacity,
        store->retired_capacity * sizeof(RetiredRange), sizeof(TermNode));
    HolTermStore *snapshot = ht_clone(store);
    assert(snapshot);
    printf("snapshot: nodes=%zu identity_capacity=%zu identity_bytes=%zu\n",
        snapshot->count, snapshot->identity_capacity, snapshot->identity_capacity * sizeof(Identity));
    printf("snapshot_history: ranges=%zu capacity=%zu bytes=%zu\n",
        snapshot->retired_count, snapshot->retired_capacity,
        snapshot->retired_capacity * sizeof(RetiredRange));
    ht_destroy(snapshot);
    ht_destroy(store);

    store = ht_create();
    HTerm x = ht_var(store, 0, 0, -1);
    HTerm y = ht_var(store, 1, 0, -1);
    HTerm c = ht_nominal(store, 1, -1);
    HTerm xc = ht_app(store, x, c, -1);
    int first = ht_unify(store, xc, y);
    assert(first == 1);
    print_wire(store, "after X c = Y, X", x);
    print_wire(store, "after X c = Y, Y", y);
    int second = ht_unify(store, y, c);
    printf("scope_counterexample: first=%d second=%d pending=%zu error=%s\n", first, second, ht_pending_count(store), ht_error(store));
    ht_destroy(store);

    store = ht_create();
    x = ht_var(store, 0, 0, -1);
    y = ht_var(store, 0, 0, 37);
    HTerm f = ht_constant(store, 0, -1);
    assert(ht_unify(store, x, ht_app(store, f, y, -1)) == 1);
    print_wire(store, "after X = f Y, X", x);
    print_wire(store, "after X = f Y, Y", y);
    ht_destroy(store);

    store = ht_create();
    x = ht_var(store, 0, 1, -1);
    y = ht_var(store, 0, 0, -1);
    assert(ht_unify(store, x, y) == 1);
    printf("mixed_type_flags: x=%d y=%d\n", ht_view(store, ht_deref(store, x)).is_type, ht_view(store, ht_deref(store, y)).is_type);
    ht_destroy(store);
    return 0;
}

