#define _POSIX_C_SOURCE 200809L
#include "term.h"
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

static double seconds(void)
{
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec / 1e9;
}

static HTerm cons(HolTermStore *s, HTerm c, HTerm typ, HTerm item, HTerm tail)
{
    return ht_app(s, ht_app(s, ht_app(s, c, typ, -1), item, -1), tail, -1);
}

int main(int argc, char **argv)
{
    if (argc != 3) return 2;
    size_t n = strtoull(argv[2], NULL, 10);
    HolTermStore *s = ht_create();
    HTerm c = ht_constant(s, 0, -1), typ = ht_constant(s, 1, -1);
    HTerm item = ht_constant(s, 2, -1), nil = ht_constant(s, 3, -1);
    HTerm list = ht_app(s, nil, typ, -1);
    for (size_t i = 0; i < n; ++i) list = cons(s, c, typ, item, list);
    size_t before = ht_heap_count(s), completed = 0;
    double begin = seconds();
    int okay = 1;
    if (argv[1][0] == 'n') {
        okay = ht_normalize(s, list, HT_NF) != HT_NONE;
    } else {
        for (size_t i = 0; i < n && okay; ++i) {
            HTerm x = ht_var(s, 0, 0, -1), xs = ht_var(s, 0, 0, -1);
            HTerm pattern = cons(s, c, typ, x, xs);
            okay = ht_unify(s, pattern, list) == 1;
            list = ht_deref(s, xs);
            completed += okay;
        }
    }
    printf("mode=%s length=%zu okay=%d completed=%zu seconds=%.6f heap_before=%zu heap_after=%zu error=%s\n", argv[1], n, okay, completed, seconds() - begin, before, ht_heap_count(s), ht_error(s));
    ht_destroy(s);
    return 0;
}
